plural <- function(n) {
  mod10 <- n %% 10
  mod100 <- n %% 100
  if (mod10 == 0 || (mod100 >= 11 && mod100 <= 19)) return("zero")
  if (mod10 == 1 && mod100 != 11) return("one")
  "other"
}

